func Flatten[T any](in [][]T) []T {
	if len(in) == 0 {
		return []T{}
	}

	// Calculate total length
	totalLen := 0
	for _, slice := range in {
		totalLen += len(slice)
	}

	// Create result slice with capacity
	result := make([]T, 0, totalLen)

	// Append all elements
	for _, slice := range in {
		result = append(result, slice...)
	}

	return result
}

