func TopK(s string, k int) []string {
	if s == "" || k <= 0 {
		return []string{}
	}

	words := strings.Fields(s)
	wordsMap := make(map[string]int)

	for _, word := range words {
		wordsMap[word]++
	}

	type wordCount struct {
		word string
		count int
	}

	wordsList := make([]wordCount, 0, len(wordsMap))
	for word, count := range wordsMap {
		wordsList = append(wordsList, wordCount{word: word, count: count})
	}

	sort.Slice(wordsList, func(i, j int) bool {
		if wordsList[i].count > wordsList[j].count {
			return true
		}
		if wordsList[i].count == wordsList[j].count {
			return wordsList[i].word < wordsList[j].word
		}
		return false
	})

	result := make([]string, 0, k)
	for i := 0; i < k && i < len(wordsList); i++ {
		result = append(result, wordsList[i].word)
	}

	return result
}

