	head, tail, size, capacity int
}

func NewRing(cap int) *Ring {
	return &Ring{
		data: make([]int, cap),
	}
}

func (r *Ring) Push(v int) {
	if r.size == r.capacity {
		r.head = (r.head + 1) % r.capacity
	} else {
		r.size++
	}
	r.data[(r.head+r.size-1)%r.capacity] = v
}

func (r *Ring) Items() []int {
	result := make([]int, r.size)
	for i := 0; i < r.size; i++ {
		result[i] = r.data[(r.head+i)%r.capacity]
	}
	return result
}

