func Rotate(m [][]int) {
	n := len(m)

	// Transpose the matrix (swap rows with columns)
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			m[i][j], m[j][i] = m[j][i], m[i][j]
		}
	}

	// Reverse each row to get the 90-degree clockwise rotation
	for i := 0; i < n; i++ {
		for j := 0; j < n/2; j++ {
			m[i][j], m[i][n-1-j] = m[i][n-1-j], m[i][j]
		}
	}
}

