func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int, len(nums))
	results := make(chan int, len(nums))

	// Send all jobs to the channel
	for _, num := range nums {
		jobs <- num
	}
	close(jobs)

	// Start worker goroutines
	for i := 0; i < workers; i++ {
		go func() {
			sum := 0
			for num := range jobs {
				sum += num
			}
		 results <- sum
		}()
	}

	// Collect results
	total := 0
	for i := 0; i < workers; i++ {
		total += <-results
	}

	return total
}

