// IntHeap implements heap.Interface and represents a min-heap of integers
type IntHeap struct {
	heap []int
}

// Len returns the length of the heap
func (h *IntHeap) Len() int {
	return len(h.heap)
}

// Less returns true if element at i is less than element at j
func (h *IntHeap) Less(i, j int) bool {
	return h.heap[i] < h.heap[j]
}

// Swap swaps elements at positions i and j
func (h *IntHeap) Swap(i, j int) {
	h.heap[i], h.heap[j] = h.heap[j], h.heap[i]
}

// Push adds an element to the heap
func (h *IntHeap) Push(x interface{}) {
	h.heap = append(h.heap, x.(int))
}

// Pop removes and returns the minimum element from the heap
func (h *IntHeap) Pop() interface{} {
 old := h.heap
 n := len(old)
 x := old[n-1]
 h.heap = old[0:n-1]
 return x
}

// PopAllSorted takes a slice of integers and returns them in ascending order
func PopAllSorted(vals []int) []int {
	h := &IntHeap{heap: make([]int, 0, len(vals))}
	heap := container_heap.New(h)

	for _, val := range vals {
		heap.Push(val)
	}

	result := make([]int, 0, len(vals))
	for heap.Len() > 0 {
		result = append(result, heap.Pop().(int))
	}

	return result
}

