// ReadChunks reads all bytes from io.Reader r and splits them into chunks
// of at most `size` bytes each. Returns a slice of byte slices where each
// slice contains at most `size` bytes.
func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	if size <= 0 {
		return nil, io.ErrShortRead
	}

	var chunks [][]byte
 buffer := make([]byte, size)

	for {
		n, err := r.Read(buffer)
		if n > 0 {
			// Create a copy of the buffer slice to avoid reference issues
			ch chunk := make([]byte, n)
			copy(chunk, buffer[:n])
			chunks = append(chunks, chunk)
		}
		if err != nil {
			if err == io.EOF {
				return chunks, nil
			}
			return nil, err
		}
		if n == 0 {
			break
		}
	}
	return chunks, nil
}

